func (e *Engine) mark(c *rubyControl, object *rubyObject, digit int64) error {
	_, err := c.enterFrame()
	if err != nil {
		return err
	}
	defer c.leaveFrame()
	if err := c.step(); err != nil {
		return err
	}
	object.trace = object.trace*10 + digit
	return nil
}

func (e *Engine) runReturn(c *rubyControl, object *rubyObject) (int64, error) {
	target, err := c.enterFrame()
	if err != nil {
		return 0, err
	}
	completion, err := e.apply(c, object, rubyReturnBlock, target)
	if err != nil {
		c.leaveFrame()
		return 0, err
	}
	if err := e.mark(c, object, rubyReturnEnsureMark); err != nil {
		c.leaveFrame()
		return 0, err
	}
	c.leaveFrame()
	if completion.kind != rubyReturn || completion.target != target {
		return 0, ErrInternal
	}
	return completion.value, nil
}

func (e *Engine) apply(c *rubyControl, object *rubyObject, block uint8, target uint64) (rubyCompletion, error) {
	_, err := c.enterFrame()
	if err != nil {
		return rubyCompletion{}, err
	}
	completion, err := e.invokeBlock(c, object, block, target)
	if err != nil {
		c.leaveFrame()
		return rubyCompletion{}, err
	}
	if completion.kind == rubyRaise {
		if err := e.mark(c, object, rubyRescueMark); err != nil {
			c.leaveFrame()
			return rubyCompletion{}, err
		}
		if err := c.step(); err != nil {
			c.leaveFrame()
			return rubyCompletion{}, err
		}
		object.value += rubyRescueAdd
		completion = rubyCompletion{kind: rubyNormal}
	}
	if err := e.mark(c, object, rubyApplyEnsureMark); err != nil {
		c.leaveFrame()
		return rubyCompletion{}, err
	}
	if err := c.step(); err != nil {
		c.leaveFrame()
		return rubyCompletion{}, err
	}
	object.value += rubyApplyEnsureAdd
	c.leaveFrame()
	return completion, nil
}

func (e *Engine) invokeBlock(c *rubyControl, object *rubyObject, block uint8, target uint64) (rubyCompletion, error) {
	_, err := c.enterFrame()
	if err != nil {
		return rubyCompletion{}, err
	}
	defer c.leaveFrame()
	switch block {
	case rubyReturnBlock:
		if err := e.mark(c, object, rubyReturnMark); err != nil {
			return rubyCompletion{}, err
		}
		if err := c.step(); err != nil {
			return rubyCompletion{}, err
		}
		return rubyCompletion{kind: rubyReturn, target: target, value: object.value + rubyReturnAdd}, nil
	case rubyRaiseBlock:
		if err := e.mark(c, object, rubyRaiseMark); err != nil {
			return rubyCompletion{}, err
		}
		if err := c.step(); err != nil {
			return rubyCompletion{}, err
		}
		return rubyCompletion{kind: rubyRaise, message: rubyRaiseMessage}, nil
	default:
		return rubyCompletion{}, ErrInternal
	}
}

// Hot is a statically proved direct Base#hot target for the persistent Alpha.
// The only dynamic guards are generation-local dispatch and shape scalars.
func (e *Engine) Hot(ctx context.Context) (int64, error) {
	if err := e.enter(ctx); err != nil {
		return 0, err
	}
	defer e.active.Store(false)
	if e.hotObject.dispatch != rubyAlphaDispatch || e.hotObject.shape != rubyAlphaShape {
		return 0, e.abort(ErrInternal)
	}
	return e.hotObject.value, nil
}

func (e *Engine) Snapshot(ctx context.Context) (State, error) {
	if err := e.enter(ctx); err != nil {
		return State{}, err
	}
	defer e.active.Store(false)
	return State{Value: e.hotObject.value, Trace: e.hotObject.trace}, nil
}

func (e *Engine) ApplyRescuedRaise(ctx context.Context, limits Limits) (State, error) {
	if err := e.enter(ctx); err != nil {
		return State{}, err
	}
	defer e.active.Store(false)
	const maxInt64 int64 = 1<<63 - 1
	const traceSuffix int64 = rubyRaiseMark*100 + rubyRescueMark*10 + rubyApplyEnsureMark
	if e.hotObject.value > maxInt64-rubyRescueAdd-rubyApplyEnsureAdd ||
		e.hotObject.trace < 0 || e.hotObject.trace > (maxInt64-traceSuffix)/1000 {
		return State{}, e.abort(ErrStateLimit)
	}
	c := rubyControl{ctx: ctx, steps: limits.Steps, frames: limits.Frames, objects: limits.Objects}
	completion, err := e.apply(&c, &e.hotObject, rubyRaiseBlock, 0)
	if err != nil {
		return State{}, e.abort(err)
	}
	if completion.kind != rubyNormal {
		return State{}, e.abort(ErrInternal)
	}
	return State{Value: e.hotObject.value, Trace: e.hotObject.trace}, nil
}

const projectionNodeCount = 3

type projectionBehavior uint8

const (
	projectionCapturedSelf projectionBehavior = iota + 1
	projectionLiveReturn
)

type ProjectionScalars struct {
	Root  int64
	Other int64
	Tail  int64
}

type projectionNode struct {
	edge   *projectionNode
	scalar int64
}

type projectionClosure struct {
	kind         projectionBehavior
	self         *projectionNode
	returnTarget uint64
}

type ProjectionEngine struct {
	active, closed     atomic.Bool
	nodes              [projectionNodeCount]*projectionNode
	root, alias, other *projectionNode
	behavior           projectionClosure
}

func ProjectionLimits() Limits { return Limits{Steps: 5, Objects: projectionNodeCount} }

func NewProjectionEngineFromScalars(ctx context.Context, scalars ProjectionScalars, limits Limits) (*ProjectionEngine, error) {
	if ctx == nil {
		return nil, ErrNilContext
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if scalars.Root != scalars.Other || !projectionCallScalarValid(scalars.Root) {
		return nil, ErrStateLimit
	}
	c := rubyControl{ctx: ctx, steps: limits.Steps, objects: limits.Objects}
	e := &ProjectionEngine{}
	values := [projectionNodeCount]int64{scalars.Root, scalars.Other, scalars.Tail}
	for index := range values {
		if err := c.step(); err != nil {
			e.clear()
			return nil, err
		}
		if err := c.object(); err != nil {
			e.clear()
			return nil, err
		}
		e.nodes[index] = &projectionNode{scalar: values[index]}
	}
	if err := c.step(); err != nil {
		e.clear()
		return nil, err
	}
	e.nodes[0].edge = e.nodes[0]
	e.nodes[1].edge = e.nodes[2]
	e.nodes[2].edge = e.nodes[0]
	e.root, e.alias, e.other = e.nodes[0], e.nodes[0], e.nodes[1]
	e.behavior = projectionClosure{kind: projectionCapturedSelf, self: e.nodes[0]}
	if err := c.step(); err != nil {
		e.clear()
		return nil, err
	}
	return e, nil
}

func projectionCallScalarValid(value int64) bool {
	delta := int64(rubyInitialLabelReturn)
	if delta > 0 {
		return value <= math.MaxInt64-delta
	}
	if delta < 0 {
		return value >= math.MinInt64-delta
	}
	return true
}

func (e *ProjectionEngine) enter(ctx context.Context) error {
	if ctx == nil {
		return ErrNilContext
	}
	if e == nil || e.closed.Load() {
		return ErrClosed
	}
	if !e.active.CompareAndSwap(false, true) {
		return ErrBusy
	}
	if e.closed.Load() {
		e.active.Store(false)
		return ErrClosed
	}
	if err := ctx.Err(); err != nil {
		e.active.Store(false)
		return err
	}
	return nil
}

func (e *ProjectionEngine) Call(ctx context.Context) (int64, error) {
	if err := e.enter(ctx); err != nil {
		return 0, err
	}
	defer e.active.Store(false)
	if e.behavior.kind != projectionCapturedSelf || e.behavior.self == nil {
		return 0, ErrNonCheckpointable
	}
	return e.behavior.self.scalar + rubyInitialLabelReturn, nil
}

func (e *ProjectionEngine) Snapshot(ctx context.Context) (ProjectionScalars, error) {
	if err := e.enter(ctx); err != nil {
		return ProjectionScalars{}, err
	}
	defer e.active.Store(false)
	tail := e.nodes[2]
	if e.root == nil || e.alias != e.root || e.other == nil || e.other == e.root ||
		e.nodes[0] != e.root || e.nodes[1] != e.other || tail == nil || tail == e.root || tail == e.other ||
		e.root.edge != e.root || e.other.edge != tail || tail.edge != e.root {
		return ProjectionScalars{}, ErrInternal
	}
	if e.behavior.kind != projectionCapturedSelf || e.behavior.returnTarget != 0 || e.behavior.self != e.root {
		return ProjectionScalars{}, ErrNonCheckpointable
	}
	return ProjectionScalars{Root: e.root.scalar, Other: e.other.scalar, Tail: tail.scalar}, nil
}

func (e *ProjectionEngine) clear() {
	if e == nil {
		return
	}
	e.nodes = [projectionNodeCount]*projectionNode{}
	e.root, e.alias, e.other = nil, nil, nil
	e.behavior = projectionClosure{}
}

func (e *ProjectionEngine) Close() error {
	if e == nil || e.closed.Load() {
		return nil
	}
	if !e.active.CompareAndSwap(false, true) {
		return ErrBusy
	}
	defer e.active.Store(false)
	e.closed.Store(true)
	e.clear()
	return nil
}
